def add_items(cases):
    for case in cases:
        app, controls = case[2], case[3]
        for c in controls:
            if c.get("role") == "MenuBarItem":
                m = M.get(app, {})
                key = c["name"] if c["name"] in m else ("Excel" if c["name"] == "Excel" else c["name"])
                if key in m and m[key]:
                    c["items"] = m[key]
